.ex_object<-function(x,name) {if(inherits(x,'CalcResult'))x<-x$value;if(is.list(x)&&!length(x))x<-structure(list(),names=character());if(!is.list(x)||is.null(names(x))) .cr_error('EXPERT_CONTRACT',paste(name,'must be an object'));x}
.ex_ids<-function(x,name,empty=FALSE) {if(is.list(x)&&is.null(names(x)))x<-if(length(x))unlist(x,use.names=FALSE)else character();if(!is.character(x)||(!empty&&!length(x))||anyNA(x)||any(!nzchar(x))||anyDuplicated(x)) .cr_error('EXPERT_CONTRACT',paste(name,'must contain distinct nonempty strings'));x}
.ex_number<-function(x,name,positive=FALSE) {a<-.cr_numeric(x,name);if(length(a)!=1L||!is.null(dim(a))||(positive&&a<=0)) .cr_error('EXPERT_CONTRACT',paste(name,'requires a finite scalar'));as.numeric(a)}
.ex_probability<-function(x,name,interior=FALSE) {v<-.ex_number(x,name);if(v<0||v>1||(interior&&v%in%c(0,1))) .cr_error('EXPERT_CONTRACT',paste(name,'outside probability domain'));v}
.ex_integer<-function(x,name,maximum=1000000) {v<-.ex_number(x,name);if(v<0||v>maximum||v!=floor(v)) .cr_error('EXPERT_CONTRACT',paste(name,'outside integer domain'));as.integer(v)}
.ex_vec<-function(x,name) {if(is.list(x)&&is.null(names(x)))x<-unlist(x,use.names=FALSE);.cr_numeric(x,name,vector_only=TRUE)}
.ex_matrix<-function(x,name) {if(is.list(x)&&is.null(names(x))){lens<-lengths(x);if(!length(x)||length(unique(lens))!=1L) .cr_error('EXPERT_CONTRACT','Rectangular rows required');x<-do.call(rbind,lapply(x,function(v)unlist(v,use.names=FALSE)))};a<-.cr_numeric(x,name);if(length(dim(a))!=2L) .cr_error('EXPERT_CONTRACT','Matrix required');a}
.ex_rows<-function(x)lapply(seq_len(nrow(x)),function(i)as.list(x[i,]))
.ex_seal<-function(v,field) {v[[field]]<-.cr_hash(v);v}
.ex_read<-function(v,field) {v<-.ex_object(v,field);seal<-v[[field]];v[[field]]<-NULL;if(!identical(seal,.cr_hash(v))) .cr_error('EXPERT_INTEGRITY','Artifact content or hash changed');v[[field]]<-seal;v}
.ex_target<-function(target,context=NULL,allowed_events='default') {t<-.ex_object(target,'target');if(!setequal(names(t),c('event','horizon','time_unit','probability_measure','conditioning'))||!(t$event%in%allowed_events)||!(t$time_unit%in%c('days','months','years'))||!(t$probability_measure%in%c('PHYSICAL','RISK_NEUTRAL'))||!is.character(t$conditioning)||length(t$conditioning)!=1L||!nzchar(t$conditioning)) .cr_error('EXPERT_TARGET','Explicit default target required');.ex_number(t$horizon,'horizon',TRUE);ctx<-.cr_result(NULL,'expert.context',context=context)$context;for(k in c('horizon','time_unit','probability_measure','conditioning'))if(!is.null(ctx[[k]])&&!identical(.cr_hash(ctx[[k]]),.cr_hash(t[[k]]))) .cr_error('TARGET_MISMATCH','Context differs from expert target');t}
.ex_elicitation<-function(contract,context=NULL) {c<-.ex_object(contract,'elicitation_contract');for(k in c('population_id','reference','known_at')).cr_string(c[[k]],k,'EXPERT_CONTRACT');.cr_data_date(c$known_at,'known_at');.ex_ids(c$expert_ids,'expert_ids');.ex_ids(c$evidence_ids,'evidence_ids');c$target<-.ex_target(c$target,context);c}

fit_elicited_beta_prior<-function(elicitation,elicitation_contract,max_cdf_error=.01,context=NULL) {
 c<-.ex_elicitation(elicitation_contract,context);e<-.ex_object(elicitation,'elicitation');mode<-e$method;tol<-.ex_number(max_cdf_error,'max_cdf_error',TRUE);if(tol>=1) .cr_error('EXPERT_CONTRACT','max_cdf_error must be below one');diagnostics<-list()
 if(identical(mode,'moments')) {
  m<-.ex_probability(e$mean,'mean',TRUE);if(('variance'%in%names(e))==('concentration'%in%names(e))) .cr_error('EXPERT_ELICITATION','Supply exactly variance or concentration')
  if('variance'%in%names(e)){v<-.ex_number(e$variance,'variance',TRUE);if(v>=m*(1-m)) .cr_error('EXPERT_ELICITATION','Variance incompatible with a proper Beta prior');concentration<-m*(1-m)/v-1}else concentration<-.ex_number(e$concentration,'concentration',TRUE)
  alpha<-m*concentration;beta<-(1-m)*concentration;residual<-numeric();diagnostics$method<-'ANALYTIC_MOMENTS'
 }else if(identical(mode,'quantiles')) {
  x<-.ex_vec(e$quantiles,'quantiles');p<-.ex_vec(e$probabilities,'probabilities');w<-.ex_vec(e$weights,'weights')
  if(length(x)<2L||length(x)!=length(p)||length(x)!=length(w)||any(x<=0|x>=1)||any(p<=0|p>=1)||any(w<=0)||any(diff(x)<=0)||any(diff(p)<=0)) .cr_error('EXPERT_ELICITATION','Increasing interior quantile/probability pairs and positive weights required')
  w<-w/max(w);w<-w/sum(w);res<-function(z)sqrt(w)*(stats::pbeta(x,exp(z[1]),exp(z[2]))-p);objective<-function(z)sum(res(z)^2)
  fits<-lapply(list(c(1,1),c(2,18),c(18,2)),function(start)stats::nlminb(log(start),objective,lower=c(-18,-18),upper=c(18,18),control=list(rel.tol=1e-12,x.tol=1e-10,abs.tol=1e-20,iter.max=3000,eval.max=6000)))
  fit<-fits[[which.min(vapply(fits,function(z)z$objective,numeric(1)))]];alpha<-exp(fit$par[1]);beta<-exp(fit$par[2]);residual<-stats::pbeta(x,alpha,beta)-p
  jac<-sapply(seq_len(2),function(i){up<-down<-fit$par;up[i]<-up[i]+1e-5;down[i]<-down[i]-1e-5;(res(up)-res(down))/2e-5});singular<-svd(jac,nu=0,nv=0)$d
  if(fit$convergence!=0L||max(abs(residual))>tol||tail(singular,1)<=1e-8*singular[1]||any(abs(fit$par)>17.99)) .cr_error('EXPERT_ELICITATION_FIT','No identified interior Beta fit within declared CDF residual tolerance')
  diagnostics<-list(method='WEIGHTED_CDF_LEAST_SQUARES',weighted_squared_error=fit$objective,max_cdf_error=max(abs(residual)),jacobian_condition=singular[1]/tail(singular,1),log_shape_bounds=list(-18,18),optimizer_status=fit$convergence)
 }else .cr_error('EXPERT_ELICITATION','method must be moments or quantiles')
 if(!is.finite(alpha+beta)||min(alpha,beta)<=0) .cr_error('EXPERT_ELICITATION','Beta shapes must be positive and finite')
 value<-.ex_seal(list(distribution='beta',alpha=alpha,beta=beta,mean=alpha/(alpha+beta),variance=(alpha/(alpha+beta))*(beta/(alpha+beta))/(alpha+beta+1),prior_concentration=alpha+beta,elicitation=e,elicitation_contract=c,known_at=c$known_at,evidence_ids=as.list(c$evidence_ids),cdf_residuals=as.list(residual)),'prior_hash')
 .cr_result(value,'expert.fit_elicited_beta_prior','probability_distribution',context,diagnostics=diagnostics,limitations='Prior concentration is elicited strength, not an observed sample size. A fitted distribution does not establish that an elicitation workshop occurred.')
}

update_expert_beta_binomial<-function(prior,defaults,exposures,observation_contract,predictive_exposures=0,credible_level=.95,context=NULL) {
 pr<-.ex_read(prior,'prior_hash');contract<-.ex_object(observation_contract,'observation_contract');base<-pr$elicitation_contract;.ex_target(base$target,context)
 if(!identical(.cr_hash(contract$target),.cr_hash(base$target))||!identical(contract$population_id,base$population_id)) .cr_error('TARGET_MISMATCH','Observation and elicitation population/target differ')
 if(!identical(contract$conditional_iid,TRUE)||!identical(contract$outcome_complete,TRUE)) .cr_error('EXPERT_OBSERVATIONS','Complete conditionally iid observations must be declared')
 ids<-.ex_ids(contract$evidence_ids,'evidence_ids');if(length(intersect(ids,unlist(pr$evidence_ids)))) .cr_error('EXPERT_DOUBLE_COUNT','Evidence already used in prior or previous updates')
 if(.cr_data_date(contract$known_at,'known_at')<.cr_data_date(pr$known_at,'known_at')) .cr_error('EXPERT_LOOKAHEAD','Observation cutoff precedes elicitation availability')
 d<-.ex_integer(defaults,'defaults');n<-.ex_integer(exposures,'exposures');future<-.ex_integer(predictive_exposures,'predictive_exposures',100000);level<-.ex_probability(credible_level,'credible_level',TRUE);if(d>n) .cr_error('EXPERT_OBSERVATIONS','defaults exceed exposures')
 a<-pr$alpha+d;b<-pr$beta+n-d;k<-0:future;pmf<-exp(lchoose(future,k)+lbeta(k+a,future-k+b)-lbeta(a,b));if(abs(sum(pmf)-1)>1e-7) .cr_error('NUMERICAL_FAILURE','Predictive probabilities do not normalize')
 posterior<-.ex_seal(list(distribution='beta',alpha=a,beta=b,mean=a/(a+b),variance=(a/(a+b))*(b/(a+b))/(a+b+1),prior_concentration=a+b,elicitation=pr$elicitation,elicitation_contract=base,known_at=contract$known_at,evidence_ids=c(pr$evidence_ids,as.list(ids)),cdf_residuals=pr$cdf_residuals,previous_prior_hash=pr$prior_hash),'prior_hash')
 .cr_result(list(posterior=posterior,posterior_mean=a/(a+b),posterior_median=stats::qbeta(.5,a,b),credible_level=level,credible_interval=as.list(stats::qbeta(c((1-level)/2,(1+level)/2),a,b)),prior_mean=pr$alpha/(pr$alpha+pr$beta),prior_weight=(pr$alpha+pr$beta)/(a+b),observed_exposures=n,observed_defaults=d,predictive_counts=as.list(k),predictive_probabilities=as.list(pmf),predictive_mean=future*a/(a+b),predictive_variance=future*(a/(a+b))*(b/(a+b))*(a+b+future)/(a+b+1),observation_contract=contract),'expert.update_expert_beta_binomial','probability_distribution',context,limitations='Credible intervals describe a common latent PD under conditionally iid binomial sampling; future counts follow a Beta-binomial. Opinion correlation is not additional independent evidence.')
}

pool_expert_probability_distributions<-function(components,weights,support,rule,exclusion_reasons=NULL,context=NULL) {
 a<-.ex_matrix(components,'components');w<-.ex_vec(weights,'weights');s<-.ex_object(support,'support');kind<-s$kind
 if(!nrow(a)||!ncol(a)||length(w)!=nrow(a)||any(a<0)||any(w<0)||sum(w)<=0) .cr_error('EXPERT_POOL','Nonnegative aligned components and nonzero weights required')
 if(identical(kind,'discrete')){values<-.ex_ids(s$values,'support values');width<-rep(1,length(values))}else if(identical(kind,'histogram')){edges<-.ex_vec(s$breaks,'breaks');if(length(edges)<2L||any(diff(edges)<=0)) .cr_error('EXPERT_POOL','Increasing histogram breaks required');width<-diff(edges)}else .cr_error('EXPERT_POOL','support kind must be discrete or histogram')
 if(ncol(a)!=length(width)||any(abs(as.vector(a%*%width)-1)>1e-10)) .cr_error('EXPERT_POOL','Every component must be normalized on common support')
 reasons<-if(is.null(exclusion_reasons))structure(list(),names=character())else .ex_object(exclusion_reasons,'exclusion_reasons')
 for(i in which(w==0)){reason<-reasons[[as.character(i-1L)]];if(!is.character(reason)||length(reason)!=1L||!nzchar(reason)) .cr_error('EXPERT_POOL','Zero-weight components require zero-based exclusion reasons')}
 w<-w/max(w);w<-w/sum(w);positive<-w>0;lognormalizer<-0
 if(identical(rule,'linear'))pooled<-as.vector(w%*%a)else if(identical(rule,'logarithmic')){logs<-colSums(log(a[positive,,drop=FALSE])*w[positive]);z<-logs+log(width);maximum<-max(z);if(!is.finite(maximum)) .cr_error('EXPERT_DISJOINT_SUPPORT','No shared positive support');lognormalizer<-maximum+log(sum(exp(z-maximum)));pooled<-exp(logs-lognormalizer)}else .cr_error('EXPERT_POOL','rule must be linear or logarithmic')
 mass<-pooled*width;mixture<-as.vector(w%*%a);tv<-.5*as.vector(abs(sweep(a,2,mixture,'-'))%*%width)
 .cr_result(list(support=s,rule=rule,normalized_weights=as.list(w),density_or_mass=as.list(pooled),bin_probabilities=as.list(mass),cumulative_probabilities=as.list(cumsum(mass)),log_normalization_constant=lognormalizer,normalization_constant=exp(lognormalizer),component_total_variation_to_linear_pool=as.list(tv),weighted_total_variation=sum(w*tv),exclusion_reasons=reasons),'expert.pool_expert_probability_distributions','probability_distribution',context,limitations='Pooling aggregates opinions, not independent observations. Histogram densities are constant inside bins; CDF values are reported at right endpoints.')
}

update_odds_from_evidence<-function(prior_pd,evidence_groups,dependence_contract,previous_evidence_ids=NULL,context=NULL) {
 p<-.ex_probability(prior_pd,'prior_pd');groups<-evidence_groups;if(!is.list(groups)||!is.null(names(groups))) .cr_error('EXPERT_EVIDENCE','evidence_groups must be a list');c<-.ex_object(dependence_contract,'dependence_contract');ids<-.ex_ids(lapply(groups,function(g)g$group_id),'group_ids',TRUE);seen<-.ex_ids(if(is.null(previous_evidence_ids))character()else previous_evidence_ids,'previous_evidence_ids',TRUE);rows<-list();log_lr<-0
 if(length(groups)>1L&&(!identical(c$conditional_independence_given_default_and_survival,TRUE)||!is.character(c$reference)||length(c$reference)!=1L||!nzchar(c$reference))) .cr_error('EXPERT_DEPENDENCE','Multiple groups require evidenced conditional independence under both outcomes')
 for(group in groups){group<-.ex_object(group,'evidence group');eids<-.ex_ids(group$evidence_ids,'evidence_ids');lr<-.ex_number(group$joint_likelihood_ratio,'joint_likelihood_ratio',TRUE);if(length(intersect(eids,seen))) .cr_error('EXPERT_DOUBLE_COUNT','Evidence appears more than once');.cr_string(group$reference,'reference','EXPERT_EVIDENCE');seen<-c(seen,eids);contribution<-log(lr);log_lr<-log_lr+contribution;rows[[length(rows)+1L]]<-list(group_id=group$group_id,evidence_ids=as.list(eids),log_odds_contribution=contribution,joint_likelihood_ratio=lr,reference=group$reference)}
 posterior<-if(p%in%c(0,1))p else stats::plogis(stats::qlogis(p)+log_lr)
 .cr_result(list(prior_pd=p,posterior_pd=posterior,total_log_likelihood_ratio=log_lr,contributions=rows,evidence_ids=as.list(sort(seen)),prior_boundary_absorbing=p%in%c(0,1),dependence_contract=c),'expert.update_odds_from_evidence','probability',context,limitations='Finite positive LRs cannot change a dogmatic zero/one prior. Correlated observations within a group require one supplied joint LR, not implicit multiplication of marginal LRs.')
}

check_expert_preference_consistency<-function(comparisons,items,incomplete_policy,tolerance=1e-8,context=NULL) {
 labels<-.ex_ids(items,'items');n<-length(labels);tol<-.ex_number(tolerance,'tolerance',TRUE);if(!(incomplete_policy%in%c('error','connected_components'))) .cr_error('EXPERT_PREFERENCE','Declare incomplete policy')
 a<-comparisons;if(is.list(a)&&is.null(names(a)))a<-do.call(rbind,lapply(a,function(row)vapply(row,function(v)if(is.null(v))NA_real_ else as.numeric(v),numeric(1))))
 if(!is.numeric(a)||!identical(dim(a),c(n,n))||any(is.infinite(a))||any(a[is.finite(a)]<=0)||any(!is.finite(diag(a)))||any(abs(log(diag(a)))>tol)) .cr_error('EXPERT_PREFERENCE','Positive square ratios and unit diagonal required')
 observed<-is.finite(a);if(any(observed!=t(observed))||any(abs(log(a[observed])+log(t(a)[observed]))>tol)) .cr_error('EXPERT_PREFERENCE','Observed pairs must be reciprocal within log tolerance');if(incomplete_policy=='error'&&!all(observed)) .cr_error('EXPERT_PREFERENCE','Incomplete comparisons prohibited')
 loga<-matrix(0,n,n);loga[observed]<-log(a[observed]);neighbors<-lapply(seq_len(n),function(i)which(observed[i,]&seq_len(n)!=i));components<-list();seen<-rep(FALSE,n)
 for(start in seq_len(n)){if(seen[start])next;stack<-start;seen[start]<-TRUE;component<-integer();while(length(stack)){i<-tail(stack,1);stack<-head(stack,-1);component<-c(component,i);for(j in neighbors[[i]])if(!seen[j]){seen[j]<-TRUE;stack<-c(stack,j)}};components[[length(components)+1L]]<-sort(component)}
 solved<-edge_residuals<-list()
 for(component in components){pairs<-list();for(i in component)for(j in component)if(i<j&&observed[i,j])pairs[[length(pairs)+1L]]<-c(i,j);design<-matrix(0,length(pairs)+1L,length(component));rhs<-rep(0,nrow(design));for(k in seq_along(pairs)){i<-pairs[[k]][1];j<-pairs[[k]][2];design[k,match(i,component)]<-1;design[k,match(j,component)]<- -1;rhs[k]<-loga[i,j]};design[nrow(design),]<-1;theta<-as.vector(qr.solve(design,rhs));priority<-exp(theta-max(theta));priority<-priority/sum(priority);solved[[length(solved)+1L]]<-list(items=as.list(labels[component]),priorities=as.list(priority));res<-as.vector(design%*%theta-rhs);for(k in seq_along(pairs))edge_residuals[[length(edge_residuals)+1L]]<-list(first=labels[pairs[[k]][1]],second=labels[pairs[[k]][2]],log_residual=res[k])}
 triads<-list();if(n>=3L)for(i in seq_len(n-2L))for(j in (i+1L):(n-1L))for(k in (j+1L):n)if(observed[i,j]&&observed[j,k]&&observed[i,k])triads[[length(triads)+1L]]<-list(items=as.list(labels[c(i,j,k)]),log_residual=loga[i,j]+loga[j,k]-loga[i,k])
 directed<-lapply(seq_len(n),function(i)which(observed[i,]&loga[i,]>tol));color<-rep(0L,n);cycles<-list()
 for(start in seq_len(n)){if(color[start]!=0L)next;path<-start;color[start]<-1L;positions<-1L;while(length(path)){at<-length(path);options<-directed[[path[at]]];position<-positions[at];if(position>length(options)){color[path[at]]<-2L;path<-head(path,-1);positions<-head(positions,-1)}else{j<-options[position];positions[at]<-position+1L;if(color[j]==0L){color[j]<-1L;path<-c(path,j);positions<-c(positions,1L)}else if(color[j]==1L)cycles[[length(cycles)+1L]]<-as.list(labels[c(path[match(j,path):length(path)],j)])}}}
 maximum<-max(c(0,vapply(edge_residuals,function(r)abs(r$log_residual),numeric(1))))
 .cr_result(list(components=solved,globally_identified=length(components)==1L,cycle_witnesses=cycles,triad_residuals=triads,pair_fit_residuals=edge_residuals,max_pair_log_residual=maximum,consistent_with_tolerance=!length(cycles)&&maximum<=tol,tolerance=tol,uncertainty_status='JUDGMENT_DISAGREEMENT_ONLY_NO_SAMPLING_MODEL'),'expert.check_expert_preference_consistency','expert_priorities',context,limitations='Ratios compare first-item to second-item importance. Log least squares diagnoses without matrix repair; disconnected components have separate priorities, no common scale. No universal cutoff or sampling interval is asserted.')
}

assess_expert_rating_agreement<-function(first_ratings,second_ratings,ordered_grades,rater_pair,weighting,missing_policy,bootstrap_indices=NULL,confidence_level=.95,context=NULL) {
 grades<-.ex_ids(ordered_grades,'ordered_grades');raters<-.ex_ids(rater_pair,'rater_pair');if(length(raters)!=2L||length(grades)<2L||length(first_ratings)!=length(second_ratings)) .cr_error('EXPERT_AGREEMENT','Two raters, aligned cases, at least two grades required');if(!(weighting%in%c('unweighted','linear','quadratic'))||!(missing_policy%in%c('error','pairwise_complete'))) .cr_error('EXPERT_AGREEMENT','Explicit weighting and missing policy required')
 pairs<-matrix(integer(),0,2);missing<-integer()
 for(i in seq_along(first_ratings)){a<-first_ratings[[i]];b<-second_ratings[[i]];if(is.null(a)||is.null(b)||is.na(a)||is.na(b)){if(missing_policy=='error') .cr_error('EXPERT_AGREEMENT','Missing rating forbidden');missing<-c(missing,i-1L);next};if(!(a%in%grades)||!(b%in%grades)) .cr_error('EXPERT_AGREEMENT','Unknown grade');pairs<-rbind(pairs,c(match(a,grades),match(b,grades)))}
 k<-length(grades);distance<-abs(outer(seq_len(k),seq_len(k),'-'))/(k-1);weights<-if(weighting=='unweighted')1*(distance==0)else 1-distance^(if(weighting=='linear')1 else 2)
 calculate<-function(rows){table<-matrix(0L,k,k);for(i in seq_len(nrow(rows)))table[rows[i,1],rows[i,2]]<-table[rows[i,1],rows[i,2]]+1L;if(!nrow(rows))return(list(table=table,observed=NULL,expected=NULL,kappa=NULL));p<-table/nrow(rows);observed<-sum(p*weights);expected<-sum(outer(rowSums(p),colSums(p))*weights);list(table=table,observed=observed,expected=expected,kappa=if(expected>=1-1e-15)NULL else (observed-expected)/(1-expected))}
 result<-calculate(pairs);interval<-NULL;valid<-invalid<-0L
 if(!is.null(bootstrap_indices)){idx<-.ex_matrix(bootstrap_indices,'bootstrap_indices');if(ncol(idx)!=nrow(pairs)||nrow(idx)<2L||!nrow(pairs)||any(idx!=floor(idx))||any(idx<0|idx>=nrow(pairs))) .cr_error('EXPERT_AGREEMENT','Zero-based paired-complete resamples with unchanged size required');values<-numeric();for(i in seq_len(nrow(idx))){v<-calculate(pairs[idx[i,]+1L,,drop=FALSE])$kappa;if(is.null(v))invalid<-invalid+1L else values<-c(values,v)};valid<-length(values);level<-.ex_probability(confidence_level,'confidence_level',TRUE);if(invalid==0L)interval<-as.list(as.numeric(stats::quantile(values,c((1-level)/2,(1+level)/2),names=FALSE,type=7)))}
 .cr_result(list(rater_pair=as.list(raters),ordered_grades=as.list(grades),weighting=weighting,confusion_matrix=.ex_rows(result$table),agreement_weights=.ex_rows(weights),observed_agreement=result$observed,expected_agreement=result$expected,kappa=result$kappa,status=if(!nrow(pairs))'NO_PAIRED_CASES'else if(is.null(result$kappa))'DEGENERATE_MARGINALS'else 'ESTIMABLE',complete_cases=nrow(pairs),total_cases=length(first_ratings),missing_case_indices=as.list(missing),bootstrap_confidence_level=if(is.null(bootstrap_indices))NULL else level,bootstrap_percentile_interval=interval,bootstrap_valid=valid,bootstrap_degenerate=invalid,uncertainty_status=if(is.null(bootstrap_indices))'NOT_REQUESTED'else if(invalid)'UNAVAILABLE_DEGENERATE_RESAMPLES'else 'PAIRED_IID_PERCENTILE'),'expert.assess_expert_rating_agreement','agreement',context,limitations='Agreement is not predictive validity. Chance agreement uses independent empirical marginals. Bootstrap assumes independent cases; clustered/repeated cases require caller-supplied cluster-valid resamples and separate interpretation. Any degenerate resample suppresses interval.')
}
